  // Check scripts for browse-locations logic or parameters
  const scripts = Array.from(document.querySelectorAll('script[src*="adc-assets/bundles"]')).map(s => s.src);
  const hits = [];
  for (const src of scripts) {
    try {
      const res = await fetch(src);
