const tabId = 118779795;
const scriptAnalysis = await browserjs(tabId, async () => {
  const res = await fetch('https://www.awxcdn.com/adc-assets/bundles/legacy-header.a8f764714cf5423afd7c.js');
  const text = await res.text();
  // find occurrences of search or autocomplete or api
  const matches = [];
  const regex = /["'`](\/[^"'`]*(?:search|location|autocomplete|geo)[^"'`]*)["'`]/gi;
  let m;
  while ((m = regex.exec(text)) !== null) {
    if (!matches.includes(m[1]) && matches.length < 30) {
      matches.push(m[1]);
    }
  }
  return matches;
});
console.log(scriptAnalysis);

