const tabId = 118779795;
const bundleSearch = await browserjs(tabId, async () => {
  // Check scripts for browse-locations logic or parameters
  const scripts = Array.from(document.querySelectorAll('script[src*="adc-assets/bundles"]')).map(s => s.src);
  const hits = [];
  for (const src of scripts) {
    try {
      const res = await fetch(src);
      const text = await res.text();
      if (text.includes('browse-locations') || text.includes('three-day-redirect')) {
        hits.push({ src, length: text.length });
        // find snippets
        const idx = text.indexOf('browse-locations');
        if (idx !== -1) {
          hits.push({ snippet: text.slice(Math.max(0, idx - 100), idx + 200) });
        }
      }
    } catch (e) {}
  }
  return hits;
});
console.log(bundleSearch);

