const airQualityData = await browserjs(tabId, () => {
  // Let's get all pollutant cards and text
  const pollutants = Array.from(document.querySelectorAll('.air-quality-pollutant, .pollutant-item, .air-quality-module, .pollutants-list, .air-quality-card, .column, .category, .pollutant-card')).map(el => ({
    tag: el.tagName,
    className: el.className,
    text: el.innerText
  }));

  // Let's also check for SO2 specifically
  const allText = document.body.innerText;
  const so2Match = allText.match(/SO2[\s\S]{0,300}/i) || allText.match(/Sulfur Dioxide[\s\S]{0,300}/i);

  return {
    pollutantsCount: pollutants.length,
    pollutants: pollutants.slice(0, 10),
    so2Match: so2Match ? so2Match[0] : null
  };
});
console.log(JSON.stringify(airQualityData, null, 2));

